const operationIrreversible = `-- name: OperationIrreversible :one
SELECT EXISTS (
    SELECT 1 FROM pc.package_pins p
    JOIN pc.action_definitions d ON d.org_id = p.org_id AND d.version_id = p.version_id
    WHERE p.org_id = $1 AND d.operation = $2
        AND convert_from(d.canonical, 'UTF8')::jsonb ->> 'reversibility' = 'irreversible'
)::bool
`

// Whether the pinned definition of an operation declares it irreversible.
func (q *Queries) OperationIrreversible(ctx context.Context, orgID ids.OrgID, operation string) (bool, error) {
	row := q.db.QueryRow(ctx, operationIrreversible, orgID, operation)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

const operationsQuarantined = `-- name: OperationsQuarantined :one
SELECT EXISTS (
    SELECT 1 FROM pc.package_pins p
    JOIN pc.package_versions v ON v.org_id = p.org_id AND v.id = p.version_id
    JOIN pc.action_definitions d ON d.org_id = v.org_id AND d.version_id = v.id
    WHERE p.org_id = $1 AND v.state IN ('QUARANTINED', 'RETIRED')
        AND (d.operation = ANY($2::text[])
             OR EXISTS (SELECT 1 FROM unnest($3::text[]) pr WHERE starts_with(d.operation, pr)))
)::bool
`

// Whether a pinned definition of one of the operations (exact names, or
// prefixes "x." of "x.*") is QUARANTINED or RETIRED (D59).
func (q *Queries) OperationsQuarantined(ctx context.Context, orgID ids.OrgID, exact []string, prefixes []string) (bool, error) {
	row := q.db.QueryRow(ctx, operationsQuarantined, orgID, exact, prefixes)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

const requestAutomationExecutionCancel = `-- name: RequestAutomationExecutionCancel :execrows
UPDATE pc.automation_executions
SET cancel_requested_by = $1, cancel_reason = $2, cancel_requested_at = now(),
    wake_at = now()
WHERE org_id = $3 AND id = $4 AND state IN ('PENDING', 'RUNNING', 'WAITING')
    AND cancel_requested_at IS NULL
`

type RequestAutomationExecutionCancelParams struct {
	RequestedBy *string
	Reason      *string
	OrgID       ids.OrgID
	ID          ids.UUID
}

// Asks an active execution to stop at its next boundary (D28); a second
// request keeps the first.
func (q *Queries) RequestAutomationExecutionCancel(ctx context.Context, arg RequestAutomationExecutionCancelParams) (int64, error) {
	result, err := q.db.Exec(ctx, requestAutomationExecutionCancel,
		arg.RequestedBy,
		arg.Reason,
		arg.OrgID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const runEffectCounts = `-- name: RunEffectCounts :one
SELECT count(*) FILTER (WHERE t.effect_state = ANY($1::text[]))::int AS matched,
       count(*) FILTER (WHERE t.effect_state IN ('UNKNOWN', 'CONFLICTING', 'UNVERIFIABLE', 'PROPAGATION_PENDING'))::int AS unknown,
       count(*) FILTER (WHERE t.effect_state = 'NONE_CONFIRMED')::int AS none_confirmed,
       count(*) FILTER (WHERE t.effect_state IS NULL AND t.decision = 'ALLOW')::int AS pending,
       count(*)::int AS total
FROM pc.transactions t
WHERE t.org_id = $2 AND t.run_id = $3 AND t.operation = $4
`

type RunEffectCountsParams struct {
	States    []string
	OrgID     ids.OrgID
	RunID     ids.UUID
	Operation string
}

type RunEffectCountsRow struct {
	Matched       int32
	Unknown       int32
	NoneConfirmed int32
	Pending       int32
	Total         int32
}

// How a run's transactions of one operation ended (F500): those in the
// wanted effect states, those whose outcome is unknown, those confirmed
// to have had no effect, and all of them.
func (q *Queries) RunEffectCounts(ctx context.Context, arg RunEffectCountsParams) (RunEffectCountsRow, error) {
	row := q.db.QueryRow(ctx, runEffectCounts,
		arg.States,
		arg.OrgID,
		arg.RunID,
		arg.Operation,
	)
	var i RunEffectCountsRow
	err := row.Scan(
		&i.Matched,
		&i.Unknown,
		&i.NoneConfirmed,
		&i.Pending,
		&i.Total,
	)
	return i, err
}

const runEffectTransactions = `-- name: RunEffectTransactions :many
SELECT t.id FROM pc.transactions t
WHERE t.org_id = $1 AND t.run_id = $2 AND t.operation = $3
    AND t.effect_state = ANY($4::text[])
ORDER BY t.created_at
LIMIT 16
`

type RunEffectTransactionsParams struct {
	OrgID     ids.OrgID
	RunID     ids.UUID
	Operation string
	States    []string
}

func (q *Queries) RunEffectTransactions(ctx context.Context, arg RunEffectTransactionsParams) ([]ids.UUID, error) {
	rows, err := q.db.Query(ctx, runEffectTransactions,
		arg.OrgID,
		arg.RunID,
		arg.Operation,
		arg.States,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ids.UUID{}
	for rows.Next() {
		var id ids.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const runTransactionCounts = `-- name: RunTransactionCounts :one
SELECT count(*)::int AS total,
       count(*) FILTER (WHERE t.effect_state IN ('UNKNOWN', 'CONFLICTING', 'UNVERIFIABLE'))::int AS unknown
FROM pc.transactions t
WHERE t.org_id = $1 AND t.run_id = $2
`

type RunTransactionCountsRow struct {
	Total   int32
	Unknown int32
}

func (q *Queries) RunTransactionCounts(ctx context.Context, orgID ids.OrgID, runID ids.UUID) (RunTransactionCountsRow, error) {
	row := q.db.QueryRow(ctx, runTransactionCounts, orgID, runID)
	var i RunTransactionCountsRow
	err := row.Scan(&i.Total, &i.Unknown)
	return i, err
}

